//! Daemon-side library code: cleanup sweeper, auto-room saga, and the
//! on-disk event persister.
//!
//! `link()` is called from the bin to ensure the `inventory` registrations
//! generated by `#[myko_saga]` / `#[myko_command]` survive dead-code
//! elimination. Message delivery itself is handled directly by the
//! `muster_entities::SendMessage` and `muster_entities::BroadcastMessage`
//! commands — there's no saga in the critical path for delivery.

pub mod auto_rooms;
pub mod cleanup;
pub mod controls;
pub mod credentials;
pub mod file_persister;
pub mod gate;
pub mod gate_filter;
pub mod hooks;
pub mod http_listener;
pub mod limits;
pub mod links;
pub mod liveness_filter;
pub mod mode;
pub mod nickname_assign;
pub mod succession;

pub fn link() {
    auto_rooms::link();
    nickname_assign::link();
}
